import { test, expect, type Browser, type Page } from '@playwright/test';
import * as path from 'path';
import { freshTotp, submitLogin } from '../specs/support';

// Generates the README screenshots in docs/images/. Not a test suite: run it with
// playwright.screenshots.config.ts (see README.md next to this file). Everything shown belongs to
// the scratch host: the throwaway member mfab-totp@example.com (reset by the fixture
// MfaBTotpReset on every run) and a TOTP secret generated by that host for this run only, which
// dies with the host's database. No real account or authenticator secret is ever on screen.
//
// The tests run in order and share state: the second registers the authenticator app that the
// third shows in the admin. Run the whole file, never one test on its own.
test.describe.configure({ mode: 'serial' });

const IMAGES = path.join(__dirname, '..', '..', '..', 'docs', 'images');

/** The throwaway member (see fixtures/MfaBTotpReset.php) and the fixtures' shared password. */
const EMAIL = 'mfab-totp@example.com';
const PASSWORD = 'Browser-Test-Pass-123!';

/** A logged-out browser context: the project's saved admin login must not apply here. */
async function visitor(browser: Browser, baseURL: string | undefined): Promise<Page> {
    const context = await browser.newContext({
        baseURL,
        storageState: { cookies: [], origins: [] },
        viewport: { width: 1280, height: 800 },
        deviceScaleFactor: 1,
    });
    return context.newPage();
}

/** Crop to the MFA app box on the login page, with a margin, so the empty page around it is left out. */
async function shootMfaApp(page: Page, file: string): Promise<void> {
    // No focus ring or hover state on whatever was clicked last.
    await page.mouse.move(5, 5);
    await page.evaluate(() => (document.activeElement as HTMLElement | null)?.blur());
    await page.waitForTimeout(400);
    const box = (await page.locator('#mfa-app').boundingBox())!;
    const margin = 32;
    const x = Math.max(0, Math.floor(box.x - margin));
    const y = Math.max(0, Math.floor(box.y - margin));
    await page.screenshot({
        path: path.join(IMAGES, file),
        clip: { x, y, width: Math.ceil(box.width + 2 * margin), height: Math.ceil(box.height + 2 * margin) },
    });
}

/**
 * Hide what only the test host has: the browser-test fixture's CMS menu entry ("MFA browser
 * reset"). Presentation only; nothing about the module's own UI is changed.
 */
async function hideFixtureChrome(page: Page): Promise<void> {
    await page.addStyleTag({ content: '.cms-menu li:has(> a[href*="admin/mfab-reset"]) { display: none !important; }' });
}

let secret = '';

test('MFA prompt after the password, with the grace-period "Setup later"', async ({ page, browser, baseURL }) => {
    expect((await page.request.get('/admin/mfab-reset/totp')).status(), 'TOTP member reset').toBe(200);
    const v = await visitor(browser, baseURL);
    await submitLogin(v, EMAIL, PASSWORD);
    await expect(v).toHaveURL(/\/Security\/login\/default\/mfa/);
    await expect(v.getByRole('button', { name: 'Setup later' })).toBeVisible();
    await shootMfaApp(v, 'login-mfa-prompt.png');
    // No shot of the next screen, the method choice: on this plain-HTTP host upstream marks the
    // security key (WebAuthn) tile "Unsupported", which would misrepresent a real HTTPS site.
    await v.context().close();
});

test('Authenticator app setup: QR code and code entry', async ({ browser, baseURL }) => {
    const v = await visitor(browser, baseURL);
    await submitLogin(v, EMAIL, PASSWORD);
    await v.getByRole('button', { name: 'Get started' }).click();
    await v.locator('.mfa-method-tile').filter({ hasText: /authenticator app/i }).click();
    await v.getByRole('button', { name: 'Next' }).click();

    const app = v.locator('#mfa-app');
    await expect(app.locator('.mfa-totp__scan-code svg')).toBeVisible();
    secret = (await app.getByText(/^[A-Z2-7]{4}( [A-Z2-7]{4})+$/).innerText()).trim();
    await shootMfaApp(v, 'totp-scan.png');

    // Finish the registration, so the next test has a member with real registered methods.
    await app.getByRole('button', { name: 'Next' }).click();
    await v.locator('#totp-code').fill(await freshTotp(secret));
    await app.getByRole('button', { name: 'Next' }).click();
    await expect(app.getByRole('heading', { name: 'Register with recovery codes' })).toBeVisible();
    await app.getByRole('button', { name: 'Finish' }).click();
    await expect(v.getByRole('heading', { name: 'Multi-factor authentication is now set up' })).toBeVisible();
    await v.context().close();
});

test("Admin: a member's registered MFA methods", async ({ page }) => {
    expect(secret, 'the previous test registered the app').not.toBe('');
    // Security admin sections are read-only until the password is re-entered (sudo mode).
    await page.goto('/admin/security');
    const grid = page.locator('#Form_EditForm_users');
    await expect(grid).toBeVisible();
    const notice = page.locator('.sudo-mode-password-field__notice-button');
    const editable = grid.locator('a.new-link');
    await expect(notice.or(editable).first()).toBeVisible();
    if (!(await editable.isVisible())) {
        await notice.click();
        await page.locator('input#SudoModePassword').fill('admin');
        await page.locator('.sudo-mode-password-field__verify-button').click();
        await expect(page.locator('.sudo-mode-password-field')).toHaveCount(0);
    }
    await grid.locator('tr.ss-gridfield-item', { hasText: EMAIL }).click();
    const methods = page.locator('#Form_ItemEditForm_AdminMFAMethods');
    await expect(methods.locator('tr.ss-gridfield-item:not(.ss-gridfield-no-items)')).toHaveCount(2);
    await hideFixtureChrome(page);
    // Upstream's MFA summary and the bundle's grid below it: scroll the edit form so the grid sits
    // at the bottom of the window, with upstream's field above it for context.
    await methods.evaluate((el) => el.scrollIntoView({ block: 'end' }));
    await page.mouse.move(5, 790);
    await page.waitForTimeout(500);
    await page.screenshot({ path: path.join(IMAGES, 'admin-registered-methods.png') });
});

test('Help page: authenticator app', async ({ page }) => {
    await page.goto('/mfa-help/totp');
    await expect(page.locator('h1')).toBeVisible();
    // The content card only; the page around it is empty.
    await page.locator('.mfa-help').screenshot({ path: path.join(IMAGES, 'help-totp.png') });
});
